const ee = require('@google/earthengine');
const privateKey = require('../auth_keys/test-project-473922-29f05d49bed7');

/*
<thinking>
1. Search strategy:
   - Use NOAA VIIRS DNB Monthly Cloud-free composites (stray-light corrected) for 2023-02 and 2023-04.
   - Dataset IDs tried in order: 'NOAA/VIIRS/DNB/MONTHLY_V1/VCMSLCFG', then 'NOAA/VIIRS/DNB/MONTHLY_V1/VCMCFG' (fallback).
   - Regions: 7 km buffers around Antakya (36.2066N, 36.1572E) and Altınözü (36.1111N, 36.2292E).
2. Masking strategy:
   - Monthly composites are already cloud-minimized. Use avg_rad as-is, clamp negatives to 0 (rad.max(0)).
   - Report pixel counts and cf_cvg mean (if available) as validation.
3. Logic for Valid Zero vs. Null/Error:
   - If collection has 0 images for either month after all fallbacks -> C1.
   - If reduceRegion count == 0 for any required stat -> C2.
   - If any mean is null/NaN -> C3.
   - Otherwise compare increases: (Apr - Feb) for both places. If Antakya increase > Altınözü increase -> A; else B.
</thinking>
*/

async function getInfoAsync(eeObject) {
  return await new Promise((resolve, reject) => {
    eeObject.getInfo((v) => resolve(v), (e) => reject(e));
  });
}

async function pickDataset() {
  const ids = [
    'NOAA/VIIRS/DNB/MONTHLY_V1/VCMSLCFG',
    'NOAA/VIIRS/DNB/MONTHLY_V1/VCMCFG'
  ];
  for (const id of ids) {
    try {
      const col = ee.ImageCollection(id).filterDate('2023-02-01', '2023-05-01');
      const size = await getInfoAsync(col.size());
      if (typeof size === 'number' && size > 0) return id;
    } catch (e) {
      // try next
    }
  }
  return null;
}

function monthImage(colId, start, end) {
  return ee.ImageCollection(colId).filterDate(start, end).first();
}

async function statsFor(img, region) {
  // Prepare bands
  const rad = img.select('avg_rad').max(0); // clamp negatives to 0
  // Compute count and mean
  const dict = rad.reduceRegion({
    reducer: ee.Reducer.combine({
      reducers: [ee.Reducer.count(), ee.Reducer.mean()],
      sharedInputs: true
    }),
    geometry: region,
    scale: 1000,
    maxPixels: 1e9
  });
  let count = null, mean = null, cfMean = null;
  try {
    const d = await getInfoAsync(dict);
    count = d && (d['avg_rad_count'] ?? d['count']);
    mean = d && (d['avg_rad_mean'] ?? d['mean']);
  } catch (e) {
    // leave as null to be handled by caller
  }
  // Try cf_cvg if present
  try {
    const cf = img.select('cf_cvg').reduceRegion({
      reducer: ee.Reducer.mean(),
      geometry: region,
      scale: 1000,
      maxPixels: 1e9
    });
    const cfd = await getInfoAsync(cf);
    cfMean = cfd && cfd['cf_cvg'];
  } catch (e) {
    cfMean = null;
  }
  return { count, mean, cfMean };
}

async function runAnalysis() {
  try {
    // 1. Geometry & Time Definitions
    const antakya = ee.Geometry.Point([36.1572, 36.2066]).buffer(7000);
    const altinozu = ee.Geometry.Point([36.2292, 36.1111]).buffer(7000);

    const feb = { start: '2023-02-01', end: '2023-03-01' };
    const apr = { start: '2023-04-01', end: '2023-05-01' };

    // 2. Data Acquisition & Check
    const dsId = await pickDataset();
    if (!dsId) {
      console.log('Dataset: Not found or inaccessible.');
      console.log('D');
      return;
    }
    console.log(`Dataset: ${dsId}`);

    const febCol = ee.ImageCollection(dsId).filterDate(feb.start, feb.end);
    const aprCol = ee.ImageCollection(dsId).filterDate(apr.start, apr.end);
    const febSize = await getInfoAsync(febCol.size());
    const aprSize = await getInfoAsync(aprCol.size());
    console.log(`Feb images: ${febSize} | Apr images: ${aprSize}`);

    if (!febSize || !aprSize || febSize === 0 || aprSize === 0) {
      console.log('C1');
      return;
    }

    const febImg = monthImage(dsId, feb.start, feb.end);
    const aprImg = monthImage(dsId, apr.start, apr.end);

    // 3. Processing and Valid Pixel Checks
    const [aFeb, aApr, zFeb, zApr] = await Promise.all([
      statsFor(febImg, antakya),
      statsFor(aprImg, antakya),
      statsFor(febImg, altinozu),
      statsFor(aprImg, altinozu)
    ]);

    const anyNullCount =
      [aFeb, aApr, zFeb, zApr].some(s => s.count === null);
    if (anyNullCount) {
      console.log('C3');
      return;
    }

    const anyZeroCount =
      [aFeb, aApr, zFeb, zApr].some(s => Number(s.count) === 0);
    if (anyZeroCount) {
      console.log('No valid pixels after masking in at least one case.');
      console.log('C2');
      return;
    }

    const anyNullMean =
      [aFeb, aApr, zFeb, zApr].some(s => s.mean === null || isNaN(Number(s.mean)));
    if (anyNullMean) {
      console.log('C3');
      return;
    }

    // 4. Calculation
    const antakyaInc = Number(aApr.mean) - Number(aFeb.mean);
    const altinozuInc = Number(zApr.mean) - Number(zFeb.mean);

    // 5. Evidence Output (concise)
    const fmt = (x) => (x == null ? 'n/a' : Number(x).toFixed(3));
    console.log(`Antakya Feb: mean=${fmt(aFeb.mean)}, px=${aFeb.count}, cf_cvg=${fmt(aFeb.cfMean)}`);
    console.log(`Antakya Apr: mean=${fmt(aApr.mean)}, px=${aApr.count}, cf_cvg=${fmt(aApr.cfMean)}`);
    console.log(`Antakya Increase: ${fmt(antakyaInc)}`);
    console.log(`Altınözü Feb: mean=${fmt(zFeb.mean)}, px=${zFeb.count}, cf_cvg=${fmt(zFeb.cfMean)}`);
    console.log(`Altınözü Apr: mean=${fmt(zApr.mean)}, px=${zApr.count}, cf_cvg=${fmt(zApr.cfMean)}`);
    console.log(`Altınözü Increase: ${fmt(altinozuInc)}`);

    // 6. Validation & Final Answer
    if (!isFinite(antakyaInc) || !isFinite(altinozuInc)) {
      console.log('C3');
      return;
    }

    if (antakyaInc > altinozuInc) {
      console.log('A: Yes');
    } else {
      console.log('B: No');
    }
  } catch (e) {
    console.log(`Error: ${e.message || e}`);
    console.log('D');
  }
}

async function initEE() {
  await new Promise((resolve, reject) => {
    ee.data.authenticateViaPrivateKey(privateKey, resolve, reject);
  });
  await new Promise((resolve, reject) => {
    ee.initialize(null, null, resolve, reject);
  });
  await runAnalysis();
}

initEE();
